189	/// A [`Tool`] that tracks how many instances run concurrently. Each
190	/// invocation bumps `current`, records the running peak into `max`, yields
191	/// several times (so the scheduler can interleave peers), then decrements.
192	pub struct ConcurrencyProbe {
193	    name: String,
194	    description: String,
195	    schema: serde_json::Value,
196	    current: Arc<AtomicUsize>,
197	    max: Arc<AtomicUsize>,
198	}
199	
200	impl ConcurrencyProbe {
201	    pub fn new(name: &str, current: Arc<AtomicUsize>, max: Arc<AtomicUsize>) -> Arc<Self> {
202	        Arc::new(Self {
203	            name: name.into(),
204	            description: format!("concurrency probe {name}"),
205	            schema: serde_json::json!({"type": "object"}),
206	            current,
207	            max,
208	        })
209	    }
210	}
211	
212	#[async_trait]
213	impl<Ctx> Tool<Ctx> for ConcurrencyProbe
214	where
215	    Ctx: Send + Sync + 'static,
216	{
217	    fn name(&self) -> &str {
218	        &self.name
219	    }
220	    fn description(&self) -> &str {
221	        &self.description
222	    }
223	    fn schema(&self) -> &serde_json::Value {
224	        &self.schema
225	    }
226	
227	    async fn invoke(
228	        &self,
229	        _ctx: &ToolContext<Ctx>,
230	        _args: serde_json::Value,
231	    ) -> Result<ToolOutput, ToolError> {
232	        let now = self.current.fetch_add(1, Ordering::SeqCst) + 1;
233	        self.max.fetch_max(now, Ordering::SeqCst);
234	        for _ in 0..8 {
235	            tokio::task::yield_now().await;
236	        }
237	        self.current.fetch_sub(1, Ordering::SeqCst);
238	        Ok(ToolOutput::new(serde_json::json!({"ok": true})))
239	    }
240	}
