130	/// Run a root agent that defers its call to `b`, and store the run in a new
131	/// session. Returns the session.
132	async fn deferred_session(b: Arc<MockTool>) -> Arc<MemorySession> {
133	    let session = Arc::new(MemorySession::new());
134	    let agent = LlmAgent::builder::<()>()
135	        .name("root")
136	        .shared_model(MockModel::with_scripts(vec![call_b_turn()]))
137	        .shared_tool(b as Arc<dyn Tool<()>>)
138	        .build();
139	    let ctx = session_ctx(&session).with_deferred_tool_calls(true);
140	    let mut recorder = SessionRecorder::new("root").with_deferral_slot(ctx.deferral_handle());
141	    let input = AgentInput::from_user_text("go");
142	    recorder.record_input(&input.messages);
143	    let events = run_events(&agent, ctx, input).await;
144	    assert!(
145	        matches!(events.last(), Some(AgentEvent::RunDeferred { .. })),
146	        "{events:?}"
147	    );
148	    for ev in &events {
149	        recorder.observe(ev);
150	    }
151	    session.append(&recorder.drain()).await.unwrap();
152	    session
153	}
