236	async fn approved_call_runs_once_with_recorded_args_before_the_new_input() {
237	    let b = MockTool::new("b", serde_json::json!({ "paid": true }));
238	    let session = deferred_session(Arc::clone(&b)).await;
239	    assert!(
240	        b.invocations().is_empty(),
241	        "the deferring run must not run b"
242	    );
243	    let (input, plan) = resume_input(&session, "root", ToolResolution::Approved).await;
244	
245	    let model = RequestLog::with_scripts(vec![text_turn("done")]);
246	    let agent = resume_agent("root", Arc::clone(&model), Arc::clone(&b)).build();
247	    let ctx = session_ctx(&session);
248	    let mut recorder = SessionRecorder::new("root").with_resume_plan(&plan);
249	    recorder.record_input(&input.messages);
250	    let events = run_events(&agent, ctx, input).await;
251	
252	    let invocations = b.invocations();
253	    assert_eq!(invocations.len(), 1, "b runs exactly once");
254	    assert_eq!(invocations[0].0, recorded_args());
255	
256	    let ks = kinds(&events);
257	    assert_eq!(
258	        ks[..3],
259	        ["RunStarted", "ToolOutputItem(call_b)", "TurnStarted(0)"],
260	        "{ks:?}"
261	    );
262	    assert_eq!(
263	        ks.last().map(String::as_str),
264	        Some("RunCompleted"),
265	        "{ks:?}"
266	    );
267	    assert_eq!(tool_output_text(&events, "call_b"), r#"{"paid":true}"#);
268	
269	    let requests = model.requests();
270	    let messages = &requests[0].messages;
271	    let n = messages.len();
272	    assert!(n >= 3, "{messages:?}");
273	    assert!(
274	        matches!(&messages[n - 3], Item::ToolCall { call_id, name, .. }
275	            if call_id == "call_b" && name == "b"),
276	        "{messages:?}"
277	    );
278	    assert!(
279	        matches!(&messages[n - 2], Item::ToolResult { call_id, .. } if call_id == "call_b"),
280	        "{messages:?}"
281	    );
282	    assert!(
283	        matches!(&messages[n - 1], Item::UserMessage { content } if text_of(content) == "next"),
284	        "{messages:?}"
285	    );
286	
287	    // The recorder puts the result before the new input, and the resume
288	    // closes the deferral.
289	    for ev in &events {
290	        recorder.observe(ev);
291	    }
292	    let resumed = recorder.drain();
293	    assert!(
294	        matches!(&resumed[0], SessionEvent::ToolReturned { call_id, .. } if call_id == "call_b"),
295	        "{resumed:?}"
296	    );
297	    assert!(
298	        matches!(&resumed[1], SessionEvent::UserMessage { .. }),
299	        "{resumed:?}"
300	    );
301	    session.append(&resumed).await.unwrap();
302	    assert!(open_deferrals(&session.events(None).await.unwrap()).is_empty());
303	}
