629	    };
630	    let result = |id: &str| Item::ToolResult {
631	        call_id: id.into(),
632	        content: vec![],
633	    };
634	    assert_tool_calls_paired(&[
635	        call("t"),
636	        call("a"),
637	        result("a"),
638	        call("b"),
639	        result("b"),
640	        result("t"),
641	    ]);
642	}
