694	async fn scripted_handoff_session(
695	    path: &[&str],
696	    mut transfer_turns: Vec<Vec<ModelEvent>>,
697	    leaf_turn: Vec<ModelEvent>,
698	) -> Arc<MemorySession> {
699	    let leaf = path.len() - 1;
700	    assert_eq!(transfer_turns.len(), leaf);
701	    let mut agent: Arc<dyn Agent<()>> = Arc::new(
702	        LlmAgent::builder::<()>()
703	            .name(path[leaf])
