705	            .shared_tool(MockTool::new("b", serde_json::json!({})) as Arc<dyn Tool<()>>)
706	            .build(),
707	    );
708	    for i in (0..leaf).rev() {
709	        agent = Arc::new(
710	            LlmAgent::builder::<()>()
711	                .name(path[i])
712	                .shared_model(MockModel::with_scripts(vec![transfer_turns.remove(i)]))
713	                .shared_handoff(agent)
714	                .build(),
715	        );
716	    }
717	    let session = Arc::new(MemorySession::new());
718	    let ctx = session_ctx(&session).with_deferred_tool_calls(true);
719	    let mut recorder = SessionRecorder::new(path[0]).with_deferral_slot(ctx.deferral_handle());
720	    let input = AgentInput::from_user_text("hi");
721	    recorder.record_input(&input.messages);
722	    let events = agent
723	        .run(ctx, input)
724	        .await
725	        .expect("run starts")
726	        .collect::<Vec<_>>()
727	        .await;
728	    assert!(
729	        matches!(events.last(), Some(AgentEvent::RunDeferred { .. })),
730	        "{events:?}"
731	    );
732	    for ev in &events {
