801	/// A copy of `session` without the results of the transfer calls (each call
802	/// id that starts with `t`).
803	async fn without_transfer_results(session: &Arc<MemorySession>) -> Arc<MemorySession> {
804	    let recorded = session.events(None).await.unwrap();
805	    let events: Vec<SessionEvent> = recorded
806	        .into_iter()
807	        .filter(|e| {
808	            !matches!(e, SessionEvent::ToolReturned { call_id, .. } if call_id.starts_with('t'))
809	        })
810	        .collect();
811	    let session = Arc::new(MemorySession::new());
812	    session.append(&events).await.unwrap();
813	    session
814	}
