913	/// As [`resume_handoff`], with the run context `ctx`.
914	async fn resume_handoff_with(
915	    session: &Arc<MemorySession>,
916	    root: &str,
917	    agent: &impl Agent<()>,
918	    ctx: RunContext<()>,
919	) -> Vec<AgentEvent> {
920	    let (input, plan) = resume_input(session, root, ToolResolution::Approved).await;
921	    let mut recorder = SessionRecorder::new(root).with_resume_plan(&plan);
922	    recorder.record_input(&input.messages);
923	    let events = run_events(agent, ctx, input).await;
924	    for ev in &events {
925	        recorder.observe(ev);
926	    }
927	    let resumed = recorder.drain();
928	    session.append(&resumed).await.unwrap();
929	    assert!(
930	        open_deferrals(&session.events(None).await.unwrap()).is_empty(),
931	        "{resumed:?}"
932	    );
933	    events
934	}
