1290	/// `messages` has `count` calls `call_id`, and a result `call_id` follows
1291	/// each call directly. Returns the result texts in call order.
1292	fn results_after_each_call(messages: &[Item], call_id: &str, count: usize) -> Vec<String> {
1293	    let mut texts = Vec::new();
1294	    for (at, item) in messages.iter().enumerate() {
1295	        if !matches!(item, Item::ToolCall { call_id: id, .. } if id == call_id) {
1296	            continue;
1297	        }
1298	        match messages.get(at + 1) {
1299	            Some(Item::ToolResult {
1300	                call_id: id,
1301	                content,
1302	            }) if id == call_id => texts.push(text_of(content)),
1303	            other => panic!("{call_id} at {at} is not closed directly after: {other:?}"),
1304	        }
1305	    }
1306	    assert_eq!(texts.len(), count, "{messages:?}");
1307	    texts
1308	}
