        &self,
        _: &RunContext<()>,
        _: GuardrailInput<'_>,
    ) -> Result<GuardrailVerdict, GuardrailError> {
        Ok(GuardrailVerdict::Tripwire {
            kind: GuardrailKind::InputPolicy,
            info: serde_json::Value::Null,
        })
    }
}

#[tokio::test]
async fn input_guardrail_tripwire_closes_the_deferral() {
