47	/// inner tool, proving the parent's permission mode crossed the boundary.
48	///
49	/// We drive the wrapper directly via `RunContext::to_tool_context()` (the idiom
50	/// the existing `agent_as_tool` tests use) rather than nesting it under an outer
51	/// LlmAgent loop: an outer loop would gate the wrapper's own (`SideEffect`) call
52	/// under `Plan` and the inner agent would never run, making the assertion a
53	/// false positive. Driving the tool directly removes the outer gate so the
54	/// inner-tool denial is unambiguously the propagated `Plan` at work.
55	#[tokio::test]
56	async fn plan_mode_propagates_into_agent_as_tool_sub_run() {
57	    let inner_tool = MockTool::new("secret_writer", serde_json::json!({"ok": true}));
58	    let inner = LlmAgent::builder::<()>()
59	        .name("inner")
60	        .description("calls a side-effecting tool")
61	        .shared_model(MockModel::with_scripts(call_then_stop("secret_writer")))
62	        .shared_tool(Arc::clone(&inner_tool) as Arc<dyn Tool<()>>)
63	        .build();
64	
65	    let wrapper = AgentAsTool::new(inner).with_name("inner");
66	
67	    let run_ctx: RunContext<()> =
68	        RunContext::ephemeral(()).with_permission_mode(PermissionMode::Plan);
69	
70	    let tc = run_ctx.to_tool_context();
71	    assert_eq!(
72	        tc.permission_mode(),
73	        PermissionMode::Plan,
74	        "tool context must carry Plan from the parent run context"
75	    );
76	
77	    let _ = wrapper
78	        .invoke(&tc, serde_json::json!({ "input": "go" }))
79	        .await
80	        .expect("sub-run completes (inner loop resumes after the denial)");
81	
82	    assert_eq!(
83	        inner_tool.invocations().len(),
84	        0,
85	        "Plan propagated into the sub-run and denied the side-effecting inner tool"
86	    );
87	}
88	
89	/// Records every `OnSubagentStop` agent name into a shared vec.
90	struct StopRecorder(Arc<Mutex<Vec<String>>>);
91	
92	#[async_trait]
93	impl Hook<()> for StopRecorder {
94	    async fn on_event(&self, _: &RunContext<()>, event: &HookEvent) -> HookDecision {
95	        if let HookEvent::OnSubagentStop { agent } = event {
96	            self.0.lock().unwrap().push(agent.clone());
97	        }
98	        HookDecision::Allow
99	    }
100	}
