102	/// Test B — a `SequentialAgent` fires `OnSubagentStop` for each child after its
103	/// stream drains. Two trivial `MockAgent` children "a" and "b"; the run-level
104	/// `HookRegistry` carries a recorder that must observe both names.
105	#[tokio::test]
106	async fn sequential_agent_fires_on_subagent_stop_per_child() {
107	    use paigasus_helikon_core::SequentialAgent;
108	
109	    let seen: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(Vec::new()));
110	
111	    let a = MockAgent::<()>::new("a", |_| Vec::new());
112	    let b = MockAgent::<()>::new("b", |_| Vec::new());
113	    let workflow = SequentialAgent::<()>::new("seq", "two steps")
114	        .then(a)
115	        .then(b);
116	
117	    let mut reg = HookRegistry::<()>::new();
118	    reg.push(Arc::new(StopRecorder(seen.clone())));
119	    let ctx: RunContext<()> = RunContext::ephemeral(()).with_hooks(reg);
120	
121	    let mut stream = workflow
122	        .run(ctx, AgentInput::from_user_text("go"))
123	        .await
124	        .expect("workflow run starts");
125	    // Drain the outer stream so every sub-agent runs to completion.
126	    use futures_util::StreamExt as _;
127	    while let Some(ev) = stream.next().await {
128	        let _ = ev as AgentEvent;
129	    }
130	
131	    let names = seen.lock().unwrap().clone();
132	    assert!(
133	        names.contains(&"a".to_owned()),
134	        "OnSubagentStop must fire for child `a`; saw {names:?}"
135	    );
136	    assert!(
137	        names.contains(&"b".to_owned()),
138	        "OnSubagentStop must fire for child `b`; saw {names:?}"
139	    );
140	}
