178	#[tokio::test]
179	async fn guard_and_redaction_config_propagates_into_agent_as_tool_sub_run() {
180	    /// Snapshot of the four SMA-414 fields as seen by the inner agent.
181	    #[derive(Default)]
182	    struct Observed {
183	        guard_rules_len: usize,
184	        default_guards: bool,
185	        redact_output: bool,
186	        extra_secrets: Vec<String>,
187	    }
