189	    let observed: Arc<Mutex<Observed>> = Arc::new(Mutex::new(Observed::default()));
190	    let obs_clone = Arc::clone(&observed);
191	
192	    let inner = MockAgent::<()>::new("probe", move |ctx| {
193	        let mut obs = obs_clone.lock().unwrap();
194	        obs.guard_rules_len = ctx.guard_rules().len();
195	        obs.default_guards = ctx.default_guards();
196	        obs.redact_output = ctx.redact_output();
197	        obs.extra_secrets = ctx.extra_secrets().to_vec();
198	        Vec::new()
199	    });
