201	    let wrapper = AgentAsTool::new(inner).with_name("probe");
202	
203	    // Parent context: two custom guard rules, extra secret, default_guards off,
204	    // redact_output off.
205	    let parent_guard_rules = GuardRule::destructive_defaults(); // non-empty slice
206	    let parent_guard_rules_len = parent_guard_rules.len();
207	    let run_ctx: RunContext<()> = RunContext::ephemeral(())
208	        .with_guard_rules(parent_guard_rules)
