240	/// Test E — SMA-415: `allow_rules` *and* `PermissionMode::DontAsk` propagate
241	/// from the parent `ToolContext` into the agent-as-tool sub-run's `RunContext`.
242	///
243	/// This is the fourth and final permission-field copy site (`handoff_child`,
244	/// `subagent_child`, and `to_tool_context` are the other three). Missing it is a
245	/// *fail-closed* propagation bug: under `DontAsk` every call is denied unless an allow rule
246	/// matches, so an agent-as-tool sub-run that lost the parent's `allow_rules`
247	/// would silently deny everything — and a unit-level inheritance test can't catch
248	/// the agent-as-tool rebuild path, only this integration test can.
249	///
250	/// Strategy mirrors Test D's lighter-probe: the wrapped `MockAgent` records
251	/// `allow_rules().len()` and `permission_mode()` off the `RunContext` it receives.
252	/// The parent carries one `AllowRule::tool("probe")` and `DontAsk`.
253	#[tokio::test]
254	async fn allow_rules_and_dont_ask_propagate_into_agent_as_tool_sub_run() {
255	    /// Snapshot of the two SMA-415 fields as seen by the inner agent.
256	    #[derive(Default)]
257	    struct Observed {
258	        allow_rules_len: usize,
259	        permission_mode: Option<PermissionMode>,
260	    }
261	
262	    let observed: Arc<Mutex<Observed>> = Arc::new(Mutex::new(Observed::default()));
263	    let obs_clone = Arc::clone(&observed);
264	
265	    let inner = MockAgent::<()>::new("probe", move |ctx| {
266	        let mut obs = obs_clone.lock().unwrap();
267	        obs.allow_rules_len = ctx.allow_rules().len();
268	        obs.permission_mode = Some(ctx.permission_mode());
269	        Vec::new()
270	    });
271	
272	    let wrapper = AgentAsTool::new(inner).with_name("probe");
273	
274	    // Parent context: one allow rule scoped to the inner agent's tool name, and
275	    // `DontAsk` (terminal/tighten-only — set once, sticks).
276	    let run_ctx: RunContext<()> = RunContext::ephemeral(())
277	        .with_allow_rules(vec![AllowRule::tool("probe")])
278	        .with_permission_mode(PermissionMode::DontAsk);
279	
280	    let tc = run_ctx.to_tool_context();
281	    assert_eq!(
282	        tc.permission_mode(),
283	        PermissionMode::DontAsk,
284	        "tool context must carry DontAsk from the parent run context"
285	    );
