294	        obs.allow_rules_len, 1,
295	        "allow_rules must propagate into the sub-run: expected 1, got {}",
296	        obs.allow_rules_len
297	    );
298	    assert_eq!(
299	        obs.permission_mode,
300	        Some(PermissionMode::DontAsk),
