335	// ── SMA-803: a sub-run cannot defer a tool call ─────────────────────────────
336	
337	/// Defers every call to tool `b`; allows the rest.
338	struct DeferB;
339	
340	#[async_trait]
341	impl PermissionPolicy<()> for DeferB {
342	    async fn check(
343	        &self,
344	        _ctx: &RunContext<()>,
345	        tool: &str,
346	        _args: &serde_json::Value,
347	    ) -> PermissionDecision {
348	        if tool == "b" {
349	            PermissionDecision::Defer {
350	                prompt: "policy says wait".to_owned(),
351	            }
352	        } else {
353	            PermissionDecision::Allow
354	        }
355	    }
356	}
