358	/// A [`MockModel`] that records the requests it receives.
359	struct CapturingModel {
360	    inner: Arc<MockModel>,
361	    requests: Mutex<Vec<ModelRequest>>,
362	}
363	
364	#[async_trait]
365	impl Model for CapturingModel {
366	    async fn invoke(
367	        &self,
368	        request: ModelRequest,
369	        cancel: CancellationToken,
370	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
371	        self.requests.lock().unwrap().push(request.clone());
372	        self.inner.invoke(request, cancel).await
373	    }
374	
375	    fn capabilities(&self) -> ModelCapabilities {
376	        ModelCapabilities::default()
377	    }
378	}
