380	/// The text of each `ToolResult` item in `items`.
381	fn tool_result_texts(items: &[Item]) -> Vec<String> {
382	    items
383	        .iter()
384	        .filter_map(|i| match i {
385	            Item::ToolResult { content, .. } => Some(
386	                content
387	                    .iter()
388	                    .filter_map(|p| match p {
389	                        ContentPart::Text { text } => Some(text.as_str()),
390	                        _ => None,
391	                    })
392	                    .collect::<String>(),
393	            ),
394	            _ => None,
395	        })
396	        .collect()
397	}
