399	async fn drain(agent: &impl Agent<()>, ctx: RunContext<()>) -> Vec<AgentEvent> {
400	    use futures_util::StreamExt as _;
401	    agent
402	        .run(ctx, AgentInput::from_user_text("go"))
403	        .await
404	        .expect("run starts")
405	        .collect()
406	        .await
407	}
408	
409	const CANNOT_DEFER: &str = "approval deferred, but this run cannot defer: ";
410	
411	/// The fourth `RunContext` copy site: `AgentAsTool` builds its sub-context with
412	/// `RunContext::new`, so the sub-run does not inherit the deferral flag. A
413	/// deferral there is a denial, and the parent run completes.
414	#[tokio::test]
415	async fn deferral_is_denied_inside_agent_as_tool_sub_run() {
416	    let inner_model = Arc::new(CapturingModel {
417	        inner: MockModel::with_scripts(call_then_stop("b")),
418	        requests: Mutex::new(Vec::new()),
419	    });
420	    let inner_b = MockTool::new("b", serde_json::json!({"ok": true}));
421	    let inner = LlmAgent::builder::<()>()
422	        .name("inner")
423	        .shared_model(Arc::clone(&inner_model))
424	        .shared_tool(Arc::clone(&inner_b) as Arc<dyn Tool<()>>)
425	        .build();
426	    let wrapper = AgentAsTool::new(inner).with_name("inner");
427	
428	    let mut parent_script = vec![vec![
429	        ModelEvent::ToolCallDelta {
430	            call_id: "p1".to_owned(),
431	            name: Some("inner".to_owned()),
432	            args_delta: r#"{"input":"go"}"#.to_owned(),
433	        },
434	        ModelEvent::Finish {
435	            reason: FinishReason::ToolCalls,
436	        },
437	    ]];
438	    parent_script.push(call_then_stop("unused").remove(1));
439	    let parent = LlmAgent::builder::<()>()
440	        .name("parent")
441	        .shared_model(MockModel::with_scripts(parent_script))
442	        .tool(wrapper)
443	        .build();
444	    let ctx = RunContext::ephemeral(())
445	        .with_deferred_tool_calls(true)
446	        .with_permission_policy(Arc::new(DeferB));
447	
448	    let events = drain(&parent, ctx).await;
449	
450	    let requests = inner_model.requests.lock().unwrap().clone();
451	    assert_eq!(
452	        requests.len(),
453	        2,
454	        "the inner loop continues after the denial"
455	    );
456	    let texts = tool_result_texts(&requests[1].messages);
457	    assert_eq!(texts.len(), 1, "{texts:?}");
458	    assert!(
459	        texts[0].starts_with(&format!("permission denied: {CANNOT_DEFER}")),
460	        "{texts:?}"
461	    );
462	    assert_eq!(inner_b.invocations().len(), 0);
463	    assert!(
464	        !events
465	            .iter()
466	            .any(|e| matches!(e, AgentEvent::RunDeferred { .. })),
467	        "{events:?}"
468	    );
469	    assert!(
470	        matches!(events.last(), Some(AgentEvent::RunCompleted { .. })),
471	        "{events:?}"
472	    );
473	}
