575	/// Each `ToolCall` has a `ToolResult` with the same call id later, with no
576	/// `UserMessage` or `AssistantMessage` between them. Each `ToolResult` closes
577	/// one earlier open `ToolCall` with its call id. A call id can repeat only
578	/// after its earlier call has a result.
579	fn assert_tool_calls_paired(messages: &[Item]) {
580	    // The calls that wait for a result, in call order.
581	    let mut outstanding: Vec<&str> = Vec::new();
582	    // A result came after the last call: the next call starts a new round.
583	    let mut seen_result_since_call = false;
584	    for item in messages {
585	        match item {
586	            Item::ToolCall { call_id, .. } => {
587	                assert!(
588	                    !outstanding.contains(&call_id.as_str()),
589	                    "call {call_id} repeats while it waits for a result: {messages:?}"
590	                );
591	                assert!(
592	                    !(seen_result_since_call && !outstanding.is_empty()),
593	                    "call {call_id} starts a new round while {outstanding:?} wait for a result: {messages:?}"
594	                );
595	                seen_result_since_call = false;
596	                outstanding.push(call_id);
597	            }
598	            Item::ToolResult { call_id, .. } => {
599	                let Some(p) = outstanding.iter().position(|c| *c == call_id.as_str()) else {
600	                    panic!("result {call_id} has no open earlier call: {messages:?}");
601	                };
602	                // Each result closes one call.
603	                outstanding.remove(p);
604	                seen_result_since_call = true;
605	            }
606	            Item::UserMessage { .. } | Item::AssistantMessage { .. } => {
607	                assert!(
608	                    outstanding.is_empty(),
609	                    "tool calls {outstanding:?} are not paired: {messages:?}"
610	                );
611	            }
612	            _ => {}
613	        }
614	    }
615	    assert!(
616	        outstanding.is_empty(),
617	        "tool calls {outstanding:?} are not paired: {messages:?}"
618	    );
619	}
