746	/// The synthetic cancel text of core 0.6.0. It must equal
747	/// `CANCELLED_TOOL_CALL_TEXT` in `session.rs`, or `project()` does not
748	/// rewrite it.
749	const CANCELLED: &str = "tool call did not complete (run cancelled/timed out)";
750	
751	/// A copy of `session` in the layout of core 0.6.0 (before SMA-810).
752	///
753	/// `session` must hold one handoff run in the current layout. This removes
754	/// each `ToolReturned` directly after a `HandoffOccurred` (the transfer
755	/// results of that handoff response) and appends a cancel result for each
756	/// removed one at the end of the run's events, in call order. The run's
757	/// events end with its `ToolDeferred` events, so the cancels come after
758	/// them, where the core 0.6.0 recorder put them.
759	async fn with_late_transfer_results(session: &Arc<MemorySession>) -> Arc<MemorySession> {
760	    let recorded = session.events(None).await.unwrap();
761	    let mut events = Vec::with_capacity(recorded.len());
762	    let mut late = Vec::new();
763	    let mut after_handoff = false;
764	    for ev in recorded {
765	        match &ev {
766	            SessionEvent::HandoffOccurred { .. } => {
767	                after_handoff = true;
768	                events.push(ev);
769	            }
770	            SessionEvent::ToolReturned {
771	                call_id, content, ..
772	            } if after_handoff => {
773	                let text = text_of(content);
774	                assert!(
775	                    text.starts_with("transferred to ")
776	                        || text.starts_with("transfer not performed"),
777	                    "{call_id} after a handoff is not a transfer result: {text}"
778	                );
779	                late.push(call_id.clone());
780	            }
781	            _ => {
782	                after_handoff = false;
783	                events.push(ev);
784	            }
785	        }
786	    }
787	    assert!(!late.is_empty(), "the log has no transfer result to move");
788	    events.extend(late.into_iter().map(|id| {
789	        SessionEvent::tool_returned(
790	            id,
791	            vec![ContentPart::Text {
792	                text: CANCELLED.to_owned(),
793	            }],
794	        )
795	    }));
796	    let legacy = Arc::new(MemorySession::new());
797	    legacy.append(&events).await.unwrap();
798	    legacy
799	}
