825	#[async_trait]
826	impl Hook<()> for CountHandoffs {
827	    async fn on_event(&self, _: &RunContext<()>, event: &HookEvent) -> HookDecision {
828	        match event {
829	            HookEvent::OnHandoff { .. } => *self.0.on_handoff.lock().unwrap() += 1,
830	            HookEvent::OnSubagentStop { agent } => {
831	                self.0.subagent_stops.lock().unwrap().push(agent.clone());
832	            }
833	            _ => {}
834	        }
835	        HookDecision::Allow
836	    }
837	}
