76	/// Run `root` with a session recorder. Returns the events and the drained log.
77	async fn recorded_run(
78	    root: &impl Agent<()>,
79	    ctx: RunContext<()>,
80	) -> (Vec<AgentEvent>, Vec<SessionEvent>) {
81	    let mut recorder = SessionRecorder::new(root.name());
82	    let input = AgentInput::from_user_text("hi");
83	    recorder.record_input(&input.messages);
84	    let events: Vec<AgentEvent> = root
85	        .run(ctx, input)
86	        .await
87	        .expect("run starts")
88	        .collect()
89	        .await;
90	    for ev in &events {
91	        recorder.observe(ev);
92	    }
93	    (events, recorder.drain())
94	}
