115	    events
116	        .iter()
117	        .filter_map(|e| match e {
118	            AgentEvent::ToolOutputItem {
119	                item: Item::ToolResult { call_id, content },
120	            } => Some((call_id.clone(), text_of(content))),
121	            _ => None,
122	        })
123	        .collect()
124	}
