126	/// A short label per event kind, for order checks.
127	fn kind(e: &AgentEvent) -> String {
128	    match e {
129	        AgentEvent::ToolCallItem {
130	            item: Item::ToolCall { call_id, .. },
131	        } => format!("call({call_id})"),
132	        AgentEvent::ToolOutputItem {
133	            item: Item::ToolResult { call_id, .. },
134	        } => format!("output({call_id})"),
135	        AgentEvent::HandoffItem { to, .. } => format!("handoff({to})"),
136	        AgentEvent::AgentUpdated { agent } => format!("updated({agent})"),
137	        AgentEvent::RunFailed { .. } => "failed".to_owned(),
138	        _ => "other".to_owned(),
139	    }
140	}
