146	/// A short label per session event.
147	fn label(e: &SessionEvent) -> String {
148	    match e {
149	        SessionEvent::UserMessage { .. } => "user".to_owned(),
150	        SessionEvent::AssistantMessage { agent, .. } => format!("assistant({agent})"),
151	        SessionEvent::ToolCalled { call_id, .. } => format!("tool_called({call_id})"),
152	        SessionEvent::ToolReturned {
153	            call_id, content, ..
154	        } => format!("tool_returned({call_id}, {})", text_of(content)),
155	        SessionEvent::HandoffOccurred { to, .. } => format!("handoff({to})"),
156	        SessionEvent::ToolDeferred { call_id, .. } => format!("tool_deferred({call_id})"),
157	        other => format!("{other:?}"),
158	    }
159	}
