165	/// No transfer result for `call_id` and no `transferred` text anywhere.
166	fn assert_no_transfer_result(events: &[AgentEvent], call_id: &str) {
167	    let outs = outputs(events);
168	    assert!(
169	        !outs.iter().any(|(id, _)| id == call_id),
170	        "no ToolOutputItem for {call_id}: {outs:?}"
171	    );
172	    assert!(
173	        !outs.iter().any(|(_, t)| t.starts_with("transferred")),
174	        "no transferred text: {outs:?}"
175	    );
176	    assert!(
177	        matches!(events.last(), Some(AgentEvent::RunFailed { .. })),
178	        "{events:?}"
179	    );
180	}
