182	/// Each `ToolCall` has a `ToolResult` with the same call id later, with no
183	/// `UserMessage` or `AssistantMessage` between them. Each `ToolResult` closes
184	/// one earlier open `ToolCall` with its call id. A call id can repeat only
185	/// after its earlier call has a result. A call after a result starts a new
186	/// round, so no call may wait for a result then.
187	fn assert_tool_calls_paired(messages: &[Item]) {
188	    let mut outstanding: Vec<&str> = Vec::new();
189	    let mut seen_result_since_call = false;
190	    for item in messages {
191	        match item {
192	            Item::ToolCall { call_id, .. } => {
193	                assert!(
194	                    !outstanding.contains(&call_id.as_str()),
195	                    "call {call_id} repeats while it waits for a result: {messages:?}"
196	                );
197	                assert!(
198	                    !(seen_result_since_call && !outstanding.is_empty()),
199	                    "call {call_id} starts a new round while {outstanding:?} wait for a result: {messages:?}"
200	                );
201	                seen_result_since_call = false;
202	                outstanding.push(call_id);
203	            }
204	            Item::ToolResult { call_id, .. } => {
205	                let Some(p) = outstanding.iter().position(|c| *c == call_id.as_str()) else {
206	                    panic!("result {call_id} has no open earlier call: {messages:?}");
207	                };
208	                outstanding.remove(p);
209	                seen_result_since_call = true;
210	            }
211	            Item::UserMessage { .. } | Item::AssistantMessage { .. } => {
212	                assert!(
213	                    outstanding.is_empty(),
214	                    "tool calls {outstanding:?} are not paired: {messages:?}"
215	                );
216	            }
217	            _ => {}
218	        }
219	    }
220	    assert!(
221	        outstanding.is_empty(),
222	        "tool calls {outstanding:?} are not paired: {messages:?}"
223	    );
224	}
