685	/// `triage → budgeting → savings`, with a model per agent from `scripts`.
686	/// Returns the root and the three models.
687	fn fc_0_chain(
688	    scripts: [Vec<Vec<ModelEvent>>; 3],
689	    b: &Arc<MockTool>,
690	) -> (Arc<dyn Agent<()>>, Vec<Arc<RequestLog>>) {
691	    let models: Vec<Arc<RequestLog>> = scripts.into_iter().map(RequestLog::with_scripts).collect();
692	    let savings = b_agent("savings", Arc::clone(&models[2]), b);
693	    let budgeting = handoff_agent("budgeting", Arc::clone(&models[1]), savings);
694	    let triage = handoff_agent("triage", Arc::clone(&models[0]), budgeting);
695	    (triage, models)
696	}
