698	/// Run `triage(fc_0) → budgeting(fc_0) → savings`, where savings defers its
699	/// call to `b`, also with the call id `fc_0`. Store the run in a new session.
700	async fn fc_0_deferred_session() -> (Arc<MemorySession>, Vec<AgentEvent>, Vec<Arc<RequestLog>>) {
701	    let b = MockTool::new("b", serde_json::json!({}));
702	    let (triage, models) = fc_0_chain(
703	        [
704	            vec![transfer_turn("fc_0", "budgeting")],
705	            vec![transfer_turn("fc_0", "savings")],
706	            vec![calls_turn(&[("fc_0", "b")])],
707	        ],
708	        &b,
709	    );
710	    let session = Arc::new(MemorySession::new());
711	    let ctx = deferring_ctx(&session).with_deferred_tool_calls(true);
712	    let mut recorder = SessionRecorder::new("triage").with_deferral_slot(ctx.deferral_handle());
713	    let input = AgentInput::from_user_text("hi");
714	    recorder.record_input(&input.messages);
715	    let events: Vec<AgentEvent> = triage
716	        .run(ctx, input)
717	        .await
718	        .expect("run starts")
719	        .collect()
720	        .await;
721	    for ev in &events {
722	        recorder.observe(ev);
723	    }
724	    session.append(&recorder.drain()).await.unwrap();
725	    assert!(b.invocations().is_empty(), "a deferred call does not run");
726	    (session, events, models)
727	}
