729	/// Resume the one open deferral of `session` as approved, with the root
730	/// `root` and the agent `agent`. Returns the events. The recorder closes the
731	/// deferral.
732	async fn resume_approved(
733	    session: &Arc<MemorySession>,
734	    root: &str,
735	    agent: &Arc<dyn Agent<()>>,
736	) -> Vec<AgentEvent> {
737	    let log = session.events(None).await.unwrap();
738	    let snapshot = session.snapshot().await.unwrap();
739	    let open = open_deferrals(&log);
740	    assert_eq!(open.len(), 1, "{open:?}");
741	    assert_eq!(open[0].call_id(), "fc_0");
742	    let input = AgentInput::from_user_text("next")
743	        .with_resolution(open[0].deferral_id(), ToolResolution::Approved);
744	    let plan = ResumePlan::from_events(&log, &snapshot, root, &input, 8).expect("valid resume");
745	    let input = input.with_resume_plan(plan.clone());
746	    let mut recorder = SessionRecorder::new(root).with_resume_plan(&plan);
747	    recorder.record_input(&input.messages);
748	    let events: Vec<AgentEvent> = agent
749	        .run(deferring_ctx(session), input)
750	        .await
751	        .expect("run starts")
752	        .collect()
753	        .await;
754	    for ev in &events {
755	        recorder.observe(ev);
756	    }
757	    session.append(&recorder.drain()).await.unwrap();
758	    assert!(
759	        open_deferrals(&session.events(None).await.unwrap()).is_empty(),
760	        "{events:?}"
761	    );
762	    events
763	}
