419	/// Each `ToolCall` has a `ToolResult` with the same call id later, with no
420	/// `UserMessage` or `AssistantMessage` between them. Each `ToolResult` closes
421	/// one earlier open `ToolCall` with its call id. A call id can repeat only
422	/// after its earlier call has a result.
423	///
424	/// Copy of `assert_tool_calls_paired` in
425	/// `crates/paigasus-helikon-core/tests/deferred_resume.rs` (pre-flight ruling
426	/// F5). Keep the two copies the same.
427	fn assert_tool_calls_paired(messages: &[Item]) {
428	    // The calls that wait for a result, in call order.
429	    let mut outstanding: Vec<&str> = Vec::new();
430	    // A result came after the last call: the next call starts a new round.
431	    let mut seen_result_since_call = false;
432	    for item in messages {
433	        match item {
434	            Item::ToolCall { call_id, .. } => {
435	                assert!(
436	                    !outstanding.contains(&call_id.as_str()),
437	                    "call {call_id} repeats while it waits for a result: {messages:?}"
438	                );
439	                assert!(
440	                    !(seen_result_since_call && !outstanding.is_empty()),
441	                    "call {call_id} starts a new round while {outstanding:?} wait for a result: {messages:?}"
442	                );
443	                seen_result_since_call = false;
444	                outstanding.push(call_id);
445	            }
446	            Item::ToolResult { call_id, .. } => {
447	                let Some(p) = outstanding.iter().position(|c| *c == call_id.as_str()) else {
448	                    panic!("result {call_id} has no open earlier call: {messages:?}");
449	                };
450	                // Each result closes one call.
451	                outstanding.remove(p);
452	                seen_result_since_call = true;
453	            }
454	            Item::UserMessage { .. } | Item::AssistantMessage { .. } => {
455	                assert!(
456	                    outstanding.is_empty(),
457	                    "tool calls {outstanding:?} are not paired: {messages:?}"
458	                );
459	            }
460	            _ => {}
461	        }
462	    }
463	    assert!(
464	        outstanding.is_empty(),
465	        "tool calls {outstanding:?} are not paired: {messages:?}"
466	    );
467	}
